const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const norwegianSea = ee.Geometry.Polygon([
    [[0, 62], [15, 62], [15, 72], [0, 72], [0, 62]]
  ]);
  const date = '2019-06-05';

  // 2. Data Acquisition - MODIS Aqua Ocean Color for chlorophyll detection
  const modisCol = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterBounds(norwegianSea)
    .filterDate(date, '2019-06-06');

  // Check if collection is empty
  const colSize = modisCol.size().getInfo();
  console.log(`MODIS Images on ${date}: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the image and chlorophyll band
  const image = modisCol.first();
  const chlorophylla = image.select('chlor_a'); // chlorophyll concentration

  // 3. Processing - Check valid pixels
  const pixelCount = chlorophylla.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: norwegianSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Valid chlorophyll pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean chlorophyll concentration
  const meanChl = chlorophylla.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: norwegianSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Mean chlorophyll (mg/m³): ${meanChl ? meanChl.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  // Check for valid calculation and bloom conditions
  // Chlorophyll > 1 mg/m³ typically indicates bloom conditions
  if (meanChl === null || meanChl === undefined || isNaN(meanChl) || meanChl < 0) {
    console.log("<answer>C3</answer>");
  } else if (meanChl > 1.0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
